    ALTER TABLE [${flyway:defaultSchema}].[Meeting] ADD
        [PredictedQuorumRiskProbability] DECIMAL(5, 4) NULL,
        [PredictedQuorumRiskBand] NVARCHAR(20) NULL,
        [PredictedQuorumRiskScoredAt] DATETIMEOFFSET NULL;
END
